import sqlite3

print('STRICT:', sqlite3.sqlite_version_info >= (3, 37, 0))
con = sqlite3.connect(':memory:', isolation_level=None)
try:
    try:
        assert con.execute("SELECT json_valid('{" + '"ok":true}' + "')").fetchone()[0] == 1
        print('JSON1: disponível')
    except sqlite3.Error as exc:
        raise SystemExit('JSON1 ausente: use um build compatível') from exc
    try:
        con.execute('CREATE VIRTUAL TABLE temp.teste_fts USING fts5(texto)')
        print('FTS5: disponível')
    except sqlite3.Error as exc:
        raise SystemExit('FTS5 ausente: use um build compatível') from exc
finally:
    con.close()

